	XOR(bh, bh);
	/* shl	bx,1 */
	SHL(bx, 1);
	/* mov	si,TaxiRoutePtrs[bx]	;si -> taxi route ptrs */
	si = *(dw*)(((db*)&taxirouteptrs)+bx);
	// 0 ;* select route wrt heading:-
	// 0 ;*
	// 0 ;* hdg N (448 ..  63 pdegs), offset = 0
	// 0 ;* hdg E ( 64 .. 191 pdegs), offset = 2
	// 0 ;* hdg S (192 .. 319 pdegs), offset = 4
	// 0 ;* hdg W (320 .. 447 pdegs), offset = 6
