	// 4433 
	/* call	CalcTaxiRngBrg */
	CALL(calctaxirngbrg, 0);
	// 0 ;--------------------
	// 0 ;* sort taxiing speed
	// 0 ;--------------------
	// 0 ;* if first waypoint then
	// 0 ;*    if range > 1,000ft then
	// 0 ;*       aiming speed = TAXI_SPEED_FAST
	// 0 ;*    else
